351:function itemsHTML(o){return `<ul class="list">${orderItems(o).map(i=>`<li>${esc(i.name)}${i.options.length?' · '+i.options.map(x=>esc(x.name)).join(', '):''} — ${money(i.total)}</li>`).join('')}</ul>`;}
354:function kitchenHTML(){const i=s.ingredients.find(i=>i.id===u.ingredient);const queue=[...s.orders].sort((a,b)=>a.received_at.localeCompare(b.received_at)||a.id-b.id);return `<div class="grid"><section class="panel"><h2>คิวครัว</h2><p class="muted">เรียงเวลาจำลองระดับวินาที แล้วเลขออเดอร์ • กดหนึ่งครั้งเลื่อนหนึ่งขั้น</p><div data-testid="kitchen-queue">${queue.map(o=>`<article class="ticket" data-testid="kitchen-order" data-order-id="${o.id}" data-received-at="${o.received_at}"><div class="split"><h3>#${o.id} · ${o.channel==='takeaway'?'สั่งกลับบ้าน '+esc(o.takeaway_id):'โต๊ะ '+esc(o.table_id)}</h3><span class="status">${statuses[o.status]}</span></div><time>${o.received_at}</time>${o.channel==='takeaway'?`<p>รับ ${esc(o.pickup_date)} ${esc(o.pickup_slot)}</p>`:''}${itemsHTML(o)}${button('btn-status-next',o.status<2?'เปลี่ยนเป็น '+statuses[o.status+1]:'เสร็จแล้ว','next-status',`data-id="${o.id}" ${o.status===2?'disabled':''}`)}</article>`).join('')||'<p class="empty">ยังไม่มีออเดอร์ในคิว</p>'}</div></section><section class="panel"><h2>ความพร้อมวัตถุดิบ</h2><label>วัตถุดิบ<select data-testid="ingredient-select">${choices(s.ingredients,u.ingredient)}</select></label><p data-testid="ingredient-status">${esc(i?.name)} · ${i?.available?'มี':'หมด'}</p><div class="row">${button('btn-out-of-stock','วัตถุดิบหมด','stock','data-available="false" class="danger"')}${button('btn-restock','กลับมามี','stock','data-available="true"')}</div><p class="muted">ผลจำลองตามแมป whole / option • เปิดคืนเมื่อไม่มีวัตถุดิบอื่นหมดค้าง และผู้จัดการไม่ได้ปิดขาย</p><p class="notice">DI-04/A-03 ยังไม่ยืนยันการเชื่อม US-20 กับ US-12/US-13</p></section></div>`;}
355:function frontHTML(){return `<section class="panel"><h2>หน้าร้าน • ออเดอร์และการรับเงิน</h2><p>ยอดแต่ละออเดอร์คงตามข้อมูลขณะส่ง • สลิปและการรับเงิน <span class="tag">จำลอง</span></p><div data-testid="front-orders">${s.orders.map(o=>{const p=payment(o),old=o.session_id&&s.sessions.find(x=>x.id===o.session_id)?.state==='closed';return `<article data-testid="front-order" data-order-id="${o.id}" data-table-id="${esc(o.table_id)}" class="ticket"><div class="split"><h3>#${o.id} · ${o.channel==='takeaway'?'สั่งกลับบ้าน '+esc(o.takeaway_id):'โต๊ะ '+esc(o.table_id)}</h3><span class="status">${statuses[o.status]}</span></div><small>${o.received_at} · ${esc(o.session_id||o.pickup_date+' '+o.pickup_slot)} ${old?'· ประวัติรอบที่ปิดแล้ว':''}</small>${itemsHTML(o)}<div class="split"><strong data-testid="front-total" class="amount">${money(o.total)}</strong><strong data-testid="front-payment-status">${p.state}</strong></div><p>วิธีที่เลือก: ${p.method==='cash'?'เงินสด':p.method==='promptpay'?'PromptPay จำลอง':'ยังไม่เลือก'}</p><div class="row">${button('btn-confirm-slip','ยืนยันสลิปจำลอง','confirm-slip',`data-id="${o.id}" ${'disabled'}`)}${button('btn-receive-cash','รับเงินสดจำลอง','receive-cash',`data-id="${o.id}" ${p.state==='จ่ายแล้ว'?'disabled':''}`)}</div></article>`;}).join('')||'<p class="empty">ยังไม่มีออเดอร์</p>'}</div></section><section class="panel"><h2>รอบโต๊ะ</h2><label>เลือกโต๊ะ<select data-testid="front-table-select">${choices(s.tables,u.frontTable,'table_id','label')}</select></label><p>${s.sessions.filter(x=>x.table_id===u.frontTable&&x.state==='open').map(x=>esc(x.id)+' · เปิดรอบ').join('')||'ไม่มีรอบที่เปิดอยู่'}</p><div class="row">${button('','เปิดรอบโต๊ะจำลอง','front-open')}${button('btn-close-table','ปิดรอบโต๊ะที่เลือก','close-table','class="danger"')}</div><p class="muted">ปิดแล้วสั่งต่อรอบเดิมไม่ได้ เก็บออเดอร์เก่าในประวัติ • mock ไม่บังคับจ่ายครบก่อนปิด เพราะ Q-16 ยังไม่ยืนยัน</p><p class="message" role="status">${esc(u.frontMessage)}</p></section><se